insert into puntos(id,nombre,pista,latitud,longitud,radio_metros,codigo_respaldo,relato,pista_extra) values (1,'En frente de la auditoría','Nivel 1: no hay tutorial. Plantate justo enfrente de la Auditoría. Acá nadie te hace code review, pero el edificio te va a mirar igual.',-34.609344,-58.39093,15,'AUDITORIA01','`classes` · «Si estás leyendo esto, el Glitch ya despertó. Soy la Arquitecta. Reconstruyan mi sistema antes de que lo borre.»','Desde el centro de la plaza, este punto queda hacia el oeste, a unos 80 m.');
insert into desafios(punto_id,idx,tipo,pregunta,opciones,respuesta_correcta) values (1,0,'opcion_multiple','¿Qué paradigma organiza el código mediante clases?','["Funcional", "Lógico", "Orientado a objetos", "Declarativo"]'::jsonb,'Orientado a objetos');
insert into puntos(id,nombre,pista,latitud,longitud,radio_metros,codigo_respaldo,relato,pista_extra) values (2,'Esquina Hotel Plaza Congreso','Esquina de un hotel que conmemora el nombre de la plaza',-34.609272,-58.390451,15,'HOTEL02','`functions` · Cada función devuelve lo mismo si le das lo mismo: eso mantiene la calma del sistema. El Glitch, en cambio, devuelve algo distinto cada vez.','Desde el punto anterior, este punto queda hacia el este, a unos 45 m.');
insert into desafios(punto_id,idx,tipo,pregunta,opciones,respuesta_correcta) values (2,0,'opcion_multiple','¿Qué paradigma se basa en funciones matemáticas?','["Funcional", "Orientado a objetos", "Imperativo", "Lógico"]'::jsonb,'Funcional');
insert into puntos(id,nombre,pista,latitud,longitud,radio_metros,codigo_respaldo,relato,pista_extra) values (3,'Banco de la Plaza','Un farol de hierro dorado, con la base toda trabajada, custodia un cantero circular de pasto. A pocos metros tenés un pedestal de piedra con una vasija enorme. Rodeá el farol y buscá el banco más cercano',-34.609278,-58.390101,15,'BANCO03','`inherit` · El código hereda su forma de otro más antiguo. Aparece una firma: «A. — Congreso OS, versión 0».','Desde el punto anterior, este punto queda hacia el este, a unos 30 m.');
insert into desafios(punto_id,idx,tipo,pregunta,opciones,respuesta_correcta) values (3,0,'opcion_multiple','¿Qué concepto permite crear una clase a partir de otra?','["Abstracción", "Polimorfismo", "Encapsulamiento", "Herencia"]'::jsonb,'Herencia');
insert into puntos(id,nombre,pista,latitud,longitud,radio_metros,codigo_respaldo,relato,pista_extra) values (4,'Cine Gaumont','Sentate cerca y mirá hacia el cine Gaumont.',-34.609262,-58.389489,15,'GAUMONT04','`poly` · Una misma orden hace cosas distintas según quién la recibe. Algo en el sistema responde de más: el Glitch está escuchando.','Desde el punto anterior, este punto queda hacia el este, a unos 55 m.');
insert into desafios(punto_id,idx,tipo,pregunta,opciones,respuesta_correcta) values (4,0,'opcion_multiple','¿Qué concepto permite que un objeto adopte diferentes comportamientos?','["Herencia", "Polimorfismo", "Clase", "Recursión"]'::jsonb,'Polimorfismo');
insert into puntos(id,nombre,pista,latitud,longitud,radio_metros,codigo_respaldo,relato,pista_extra) values (5,'Parque de juegos','Parate entre el "Pensador de Rodin" y el mastil con la bandera nacional, mira a los costados.',-34.609676,-58.388167,15,'JUEGOS05','`class` · Ya hay suficientes moldes para crear el mapa. La plaza se dibuja en la pantalla como un diagrama de flujo.','Desde el punto anterior, este punto queda hacia el este, a unos 130 m.');
insert into desafios(punto_id,idx,tipo,pregunta,opciones,respuesta_correcta) values (5,0,'opcion_multiple','¿Cómo se llama el molde que permite crear objetos?','["Método", "Variable", "Instancia", "Clase"]'::jsonb,'Clase');
insert into puntos(id,nombre,pista,latitud,longitud,radio_metros,codigo_respaldo,relato,pista_extra) values (6,'Monumento Kilometro 0','Pasando la entrada a un misterioso garaje, encontraras una estatua que habla de kilometraje.',-34.609561,-58.388889,15,'KM06','`loop` · Paso a paso, el sistema recupera su ritmo. El Glitch repite un mismo mensaje en bucle: «línea 1, línea 1, línea 1…».','Desde el punto anterior, este punto queda hacia el oeste, a unos 65 m.');
insert into desafios(punto_id,idx,tipo,pregunta,opciones,respuesta_correcta) values (6,0,'opcion_multiple','¿Qué paradigma se basa en instrucciones paso a paso?','["Lógico", "Declarativo", "Imperativo", "Funcional"]'::jsonb,'Imperativo');
insert into puntos(id,nombre,pista,latitud,longitud,radio_metros,codigo_respaldo,relato,pista_extra) values (7,'Circunferencia del piso','Acá el piso dibuja una circunferencia: parate adentro y recorré el borde, que es lo más cerca que vas a estar de un código con sentido.',-34.609512,-58.389489,15,'PISO07','`private` · Los datos internos quedan a salvo tras una puerta que solo el sistema puede abrir. El Glitch retrocede.','Desde el punto anterior, este punto queda hacia el oeste, a unos 55 m.');
insert into desafios(punto_id,idx,tipo,pregunta,opciones,respuesta_correcta) values (7,0,'opcion_multiple','¿Qué elemento de la POO protege los datos internos de un objeto?','["Herencia", "Encapsulamiento", "Polimorfismo", "Abstracción"]'::jsonb,'Encapsulamiento');
insert into puntos(id,nombre,pista,latitud,longitud,radio_metros,codigo_respaldo,relato,pista_extra) values (8,'Monumento Ricardo Balbín','Un camino de tierra con borde de piedra curvo y troncos enormes que tienen más historial que un repo de 2010. Buscá el monumento a Ricardo Balbín y pasá a sus espaldas.',-34.609887,-58.389671,15,'BALBIN08','`query` · Ahora el sistema pide qué resultado quiere sin explicar cada paso. Una nota de la Arquitecta: «El Glitch no es un virus».','Desde el punto anterior, este punto queda hacia el sur, a unos 45 m.');
insert into desafios(punto_id,idx,tipo,pregunta,opciones,respuesta_correcta) values (8,0,'opcion_multiple','¿Qué paradigma describe qué resultado se quiere sin detallar los pasos?','["Declarativo", "Estructurado", "Imperativo", "Procedural"]'::jsonb,'Declarativo');
insert into puntos(id,nombre,pista,latitud,longitud,radio_metros,codigo_respaldo,relato,pista_extra) values (9,'Fuente Principal','Con el Congreso de fondo y las fuentes detrás, entre un farol de varios brazos y otro pedestal con vasija, hay una reja alta negra y palomas con más prioridad que vos. Es la fuente principal: no hace falta entrar, ubicate del lado de afuera, en la vereda de baldosas, a su derecha.',-34.609513,-58.390162,15,'FUENTE09','`recursion` · Cada fragmento guarda un recuerdo de los anteriores, como una función que se llama a sí misma. Falta poco.','Desde el punto anterior, este punto queda hacia el noroeste, a unos 60 m.');
insert into desafios(punto_id,idx,tipo,pregunta,opciones,respuesta_correcta) values (9,0,'opcion_multiple','¿Cómo se llama una función que puede llamarse a sí misma?','["Lambda", "Bucle", "Recursión", "Callback"]'::jsonb,'Recursión');
insert into puntos(id,nombre,pista,latitud,longitud,radio_metros,codigo_respaldo,relato,pista_extra) values (10,'Estatua y Congreso','La escalinata del Congreso asomando atrás. Mirá el piso: hay una tapa de hierro con letras grabadas. Entre la estatua y el Congreso, pegadito a la reja.',-34.609702,-58.391206,15,'CONGRESO10','`prolog` · Aparecen reglas escritas en lógica. Una dice: «Si un comentario no se cierra, todo lo que sigue se ignora».','Desde el punto anterior, este punto queda hacia el oeste, a unos 100 m.');
insert into desafios(punto_id,idx,tipo,pregunta,opciones,respuesta_correcta) values (10,0,'opcion_multiple','¿Qué lenguaje se asocia con la programación lógica?','["Java", "Python", "Haskell", "Prolog"]'::jsonb,'Prolog');
insert into puntos(id,nombre,pista,latitud,longitud,radio_metros,codigo_respaldo,relato,pista_extra) values (11,'Biblioteca y Estatua','Entre la historia y los libros... ubicate justo en el medio entre la biblioteca y la estatua.',-34.610029,-58.391016,15,'BIBLIO11','`abstract` · Solo queda lo esencial. Detrás de todo el código hay una única línea que nadie había leído.','Desde el punto anterior, este punto queda hacia el sureste, a unos 40 m.');
insert into desafios(punto_id,idx,tipo,pregunta,opciones,respuesta_correcta) values (11,0,'opcion_multiple','¿Qué concepto de la POO oculta detalles internos y muestra lo esencial?','["Instanciación", "Abstracción", "Herencia", "Polimorfismo"]'::jsonb,'Abstracción');
insert into puntos(id,nombre,pista,latitud,longitud,radio_metros,codigo_respaldo,relato,pista_extra) values (12,'Vereda 10 de Diciembre','Apoyá un pie en esa vereda democrática y considerate libre de errores, compilado y listo.',-34.609701,-58.391384,15,'VEREDA12','`facts` · Última pieza: hechos y reglas que unen todo el sistema. Está listo para compilar.','Desde el punto anterior, este punto queda hacia el noroeste, a unos 50 m.');
insert into desafios(punto_id,idx,tipo,pregunta,opciones,respuesta_correcta) values (12,0,'opcion_multiple','¿Qué paradigma usa reglas y hechos para obtener conclusiones?','["Lógico", "Imperativo", "Orientado a Objetos", "Funcional"]'::jsonb,'Lógico');
insert into juego_config(id,data) values (1,'{"duracion_minutos": 240, "puntaje": {"por_acierto": 100, "bonus_max_velocidad": 50, "penal_error": 10, "penal_respaldo": 30, "penal_pista": 15}, "final": "🎉 ¡COMPILACIÓN EXITOSA! El Glitch era un comentario sin cerrar en la línea 1, un error de la propia Arquitecta. Al corregirlo, el sistema vuelve a funcionar y la plaza queda protegida. Los debuggers lo lograron: recuperaron el código perdido trabajando en equipo."}'::jsonb) on conflict (id) do update set data=excluded.data;
insert into partidas(codigo) values ('PLAZA-2026') on conflict (codigo) do nothing;
